<?php require 'includes/db.php'; require 'includes/auth.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];header('Location: account.php');exit;}$error='Invalid email or password.';}require 'includes/header.php';?><div class="form-card"><h1>Log in</h1><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Log In</button></form><p>New user? <a href="signup.php">Create account</a></p></div><?php require 'includes/footer.php';?>